insert into public.ingredient_allergen_profiles (
  ingredient_id,
  dataset_version,
  source_ids,
  source_ref,
  review_kind,
  composition_status
)
select
  i.id,
  'ingredient-allergens-es-v1',
  p.source_ids,
  p.source_ref,
  p.review_kind,
  p.composition_status
from profile_data p
join public.ingredients i on i.normalized_name = p.normalized_name;

